design.compositionCss:
/* Indigo Screening Room: original dark cinema composition. */
.shell{display:grid;grid-template-columns:220px minmax(0,1fr)}
.sidebar{display:flex;flex-direction:column;position:sticky;top:0;height:100dvh;padding:28px 16px;gap:18px;border:0;border-right:1px solid var(--weekly-soft);overflow-y:auto}
.brand{margin:0 0 16px;gap:10px}
.brand strong{font-family:var(--body);font-size:14px;font-weight:600;line-height:1.3}
.brand small{font-size:10px;line-height:1.5}
.sidebar nav{display:grid;grid-template-columns:minmax(0,1fr);gap:5px}
.nav-item{display:flex;align-items:center;gap:12px;border:0;border-radius:8px;min-height:45px;padding:11px 12px;font-family:var(--body);font-size:12px;line-height:1.4}
.nav-item span{display:block;font-family:var(--body);font-size:10px;min-width:20px;margin:0;letter-spacing:.04em}
.sidebar-foot{display:grid;grid-template-columns:minmax(0,1fr);margin-top:auto;gap:8px;padding-top:20px;border:0}
.sidebar-foot .quiet{min-width:0;border-radius:8px;text-align:left}
main{max-width:1580px;margin:0 auto;padding:0 36px 72px}
.topbar{min-height:116px;margin-bottom:28px;padding:26px 0;border:0}
.topbar h1{font-family:var(--body);font-size:clamp(27px,3vw,39px);font-weight:600;line-height:1.25;letter-spacing:-.045em;max-width:850px}
.topbar .eyebrow,.eyebrow{color:var(--weekly-mark)}
.primary,.quiet{border-radius:8px;min-height:44px;font-size:12px}
.primary{background:var(--acid);color:var(--stage);border-color:var(--acid)}
.quiet{background:var(--panel);color:var(--ink);border-color:var(--weekly-soft)}
.panel,.module,.resource,.phase,.evidence-card,.production,.daily-review,.stat-card:nth-child(n),.cinema-film{border:1px solid var(--weekly-soft);border-radius:12px;box-shadow:none;padding:24px}
.panel h2,.intro-panel h2{font-family:var(--body);font-weight:600;font-size:24px;line-height:1.35;letter-spacing:-.035em;border:0;padding:0}
.panel h3{font-family:var(--body);font-weight:600;font-size:20px;line-height:1.4}
.panel .eyebrow{color:var(--weekly-mark)}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:480px;padding:36px 40px;border:1px solid var(--weekly-soft);border-left:5px solid var(--weekly-mark);border-radius:18px}
.poster-focus h2{font-family:var(--script);font-weight:600;font-size:clamp(74px,8vw,112px);line-height:.98;letter-spacing:-.055em;max-width:810px;margin-bottom:28px;text-decoration:none}
.poster-focus h2 span{font-family:var(--script);font-style:italic;font-weight:600;font-size:1em;line-height:1.02;letter-spacing:-.055em;margin-top:4px;text-decoration:none}
.poster-focus .hero-script{font-family:var(--body);font-size:17px!important;font-weight:400;line-height:1.5;letter-spacing:.04em;margin:0 0 22px}
.poster-focus .cinema-scene{width:49%;right:0;top:0;bottom:0;transform:none;opacity:.55}
.poster-focus .progress-wrap{max-width:370px;margin-top:28px}
.poster-focus .hero-choices{gap:10px}
.hero-grid .stat-card{grid-column:auto;grid-row:auto;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:6px 12px;min-height:110px;padding:22px;border:1px solid var(--weekly-soft);border-radius:12px;background:var(--panel)}
.hero-grid .stat-card strong{grid-column:2;grid-row:1/3;font-family:var(--script);font-weight:600;font-style:normal;font-size:43px;line-height:1;letter-spacing:-.04em;margin:0}
.hero-grid .stat-card span{font-size:10px;line-height:1.6;letter-spacing:.02em}
.hero-grid .stat-card small{font-size:10px;line-height:1.5}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;border:0;margin:26px 0 32px}
.studio-programme button{border:1px solid var(--weekly-soft)!important;border-bottom:3px solid var(--weekly-mark)!important;border-radius:12px;min-height:112px;padding:22px!important;background:var(--panel);box-shadow:none}
.studio-programme span{font-family:var(--body);font-size:17px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.module{border-left:3px solid var(--weekly-mark)}
.module h3{font-family:var(--script);font-size:32px;font-weight:600;line-height:1.15;letter-spacing:-.035em}
.module-head small{font-family:var(--body);font-size:11px;font-style:normal;line-height:1.6}
.topic{font-size:13px;line-height:1.6}
.roadmap{display:grid;columns:auto;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.phase:nth-child(n){display:block;margin:0!important;min-height:270px;padding:25px;border:1px solid var(--weekly-soft);border-top:3px solid var(--weekly-mark);border-radius:12px}
.phase h3{font-family:var(--script);font-size:33px;font-weight:600;line-height:1.15;letter-spacing:-.03em}
.phase small{font-family:var(--body);font-size:10px;letter-spacing:.12em}
.resource-list{grid-template-columns:minmax(0,1fr);gap:16px}
.resource{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr) auto;gap:24px;padding:25px;border:1px solid var(--weekly-soft);border-left:3px solid var(--weekly-mark);border-radius:12px}
.resource h3{font-family:var(--body);font-size:17px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.evidence-card{border-left:3px solid var(--weekly-mark)}
.evidence-card label{font-family:var(--body);font-size:15px;line-height:1.5}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;border:0}
.cinema-film{padding:24px;border:1px solid var(--weekly-soft);border-top:3px solid var(--weekly-mark);border-radius:14px}
.film-cover{min-height:330px;border:0;border-radius:10px;background:var(--weekly-soft);box-shadow:none}
.cinema-film .film-cover h3{font-family:var(--script);font-size:51px;font-weight:600;line-height:1.02;letter-spacing:-.035em}
.film-cover h3 small,.cover-caption{color:var(--ink)}
.cinema-intro{border:1px solid var(--weekly-soft);border-radius:18px;padding:32px}
.cinema-intro h2{font-family:var(--script);font-weight:600;font-size:clamp(40px,4.5vw,64px);line-height:1.15;letter-spacing:-.035em}
.cinema-source-note,.cinema-credits,.meta,.studio-footer{color:var(--ink)}
.journal-masthead{padding:30px 0;border-bottom:1px solid var(--weekly-soft)}
.journal-masthead h2{font-family:var(--script);font-weight:600;font-size:clamp(76px,8vw,112px);line-height:1.08;letter-spacing:-.055em}
.journal-masthead h2 em{font-family:var(--script);font-weight:500;font-size:.9em;line-height:1.15;font-style:italic;letter-spacing:-.04em}
.journal-seal{border:1px solid var(--weekly-mark);border-radius:50%;background:var(--panel);transform:rotate(-8deg)}
.journal-workbench{grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:24px}
.journal-bridge{transform:none}
.journal-section-title{border-top:1px solid var(--weekly-soft)}
.journal-section-title h2{font-family:var(--body);font-size:25px;font-weight:600;line-height:1.3;letter-spacing:-.03em}
#view-journal .journal-deck{gap:22px}
.diary-card:not(.poster-card){transform:none;margin:0;border:1px solid var(--weekly-soft);border-radius:12px;padding:24px;box-shadow:none}
.diary-card:not(.poster-card) h3{font-family:var(--script);font-size:48px;font-weight:600;line-height:1.1}
#view-journal .diary-card.poster-card{border-radius:10px}
.journal-empty{border-color:var(--weekly-soft);border-radius:12px}
.journal-empty h3{font-size:44px;line-height:1.2}
.form-panel input,.form-panel select,.form-panel textarea,.filter-row input,.filter-row select{border:1px solid var(--weekly-soft);border-radius:8px;background:var(--stage);color:var(--ink)}
.filter-row{border:1px solid var(--weekly-soft);border-radius:12px;background:var(--panel)}
.tag{border-radius:5px}
@media(max-width:1100px) and (min-width:761px){
.shell{grid-template-columns:190px minmax(0,1fr)}
.sidebar nav{grid-template-columns:minmax(0,1fr)}
main{padding:0 24px 64px}
.roadmap{grid-template-columns:repeat(2,minmax(0,1fr))}
.evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.journal-workbench{grid-template-columns:minmax(0,1fr)}
}
@media(max-width:760px){
.shell{display:block}
.sidebar{display:block;position:relative;height:auto;padding:20px;border:0;border-bottom:1px solid var(--weekly-soft)}
.brand{margin:0}
.sidebar-foot{display:flex;flex-wrap:wrap;margin-top:14px;padding:0}
.sidebar-foot .quiet{font-size:10px;padding:10px}
main{padding:0 20px 56px}
.topbar{padding:24px 0;margin-bottom:20px;min-height:0}
.topbar h1{font-size:28px;line-height:1.3;letter-spacing:-.035em}
.top-actions{margin-top:14px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:480px;padding:28px 22px;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark);border-radius:16px}
.poster-focus h2{font-size:clamp(54px,15vw,80px);line-height:1.08;letter-spacing:-.055em}
.poster-focus .hero-script{font-size:15px!important;line-height:1.6}
.poster-focus .cinema-scene{width:80%;right:-20%;opacity:.35}
.hero-grid .stat-card{display:flex;flex-direction:column;align-items:start;min-height:124px;padding:16px 10px;gap:6px;border:1px solid var(--weekly-soft)}
.hero-grid .stat-card strong{font-size:32px;margin:4px 0}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:9px;letter-spacing:0}
.studio-programme,.syllabus-grid,.roadmap,.resource-list,.evidence-grid,.cinema-grid{grid-template-columns:minmax(0,1fr);gap:16px}
.studio-programme button{min-height:98px;padding:22px!important}
.studio-programme span{font-size:17px}
.panel,.module,.resource,.evidence-card,.production,.daily-review,.cinema-film{padding:22px}
.panel h2,.intro-panel h2{font-size:23px;line-height:1.35}
.phase:nth-child(n){min-height:0;padding:24px}
.phase h3{font-size:30px}
.resource{display:block}
.resource h3{font-size:17px}
.film-cover{min-height:280px}
.cinema-film .film-cover h3{font-size:43px;line-height:1.08}
.journal-masthead h2{font-size:clamp(52px,14.5vw,74px);line-height:1.2;overflow-wrap:anywhere}
.journal-masthead h2 em{font-size:.9em;line-height:1.2}
#view-journal .journal-workbench{grid-template-columns:minmax(0,1fr)}
#view-journal .journal-workbench :is(.form-panel,.journal-bridge){min-width:0;max-width:100%}
#view-journal .journal-workbench :is(form,details,label,small,p,div){min-width:0;max-width:100%;overflow-wrap:anywhere}
#view-journal .form-panel,#view-journal .form-row{grid-template-columns:minmax(0,1fr)}
#view-journal .panel-head{flex-direction:column;align-items:start}
#view-journal .journal-workbench :is(input,select,textarea){min-width:0;max-width:100%;width:100%;box-sizing:border-box}
#view-journal .journal-check input{flex-shrink:0}
#view-journal .journal-workbench :is(button,a){max-width:100%;white-space:normal;overflow-wrap:anywhere}
#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}
#view-journal .diary-card:nth-child(n){transform:none;box-shadow:none}
#view-journal .journal-empty{min-width:0;padding:34px 14px}
#view-journal .journal-empty h3{font-size:38px;overflow-wrap:anywhere}
#view-journal .journal-watch-shelf{min-width:0;overflow-wrap:anywhere}
#view-journal .watch-ticket{flex-wrap:wrap}
}
/* Original screening-room extension: split proscenium, chapter rows and paired archive sheets. */
