.phase h3{font-family:var(--display);font-size:24px;line-height:1.3;letter-spacing:-.04em}
.phase ul{margin:0}
.resource-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.resource{display:block;border-left:1px solid var(--weekly-soft);border-bottom:3px solid var(--weekly-mark)}
.resource div{margin-bottom:16px}
.cinema-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.cinema-film{padding:20px}
.cinema-film:nth-child(n) .film-cover{transform:none}
.film-cover{min-height:300px;padding:24px 18px}
.cinema-film .film-cover h3{font-family:var(--script);font-size:44px;line-height:1.08}
.cover-caption{transform:none;border:0;border-radius:4px;background:var(--panel)}
.journal-masthead h2{font-family:var(--display);font-weight:400;font-size:clamp(65px,7vw,100px);line-height:1.15;letter-spacing:-.06em}
.journal-masthead h2 em{font-family:var(--script);font-size:.9em;line-height:1.2;text-decoration:none}
