.shell{grid-template-columns:184px minmax(0,1fr)}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr))}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:480px}
.hero-grid .stat-card{grid-column:auto;min-height:130px}
