}
@media(max-width:760px){
.shell{display:block}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:490px;padding:28px 22px;border-left:1px solid var(--weekly-soft);border-top:3px solid var(--weekly-mark)}
.poster-focus h2{font-size:clamp(44px,12.3vw,66px);line-height:1.15}
.poster-focus .hero-script{font-size:24px!important}
.poster-focus .cinema-scene{width:78%;right:-18%;opacity:.3}
.poster-focus .hero-star{width:30px;height:30px}
.hero-grid .stat-card{grid-column:auto;grid-row:auto;min-height:126px;padding:16px 10px}
.hero-grid .stat-card strong{font-size:34px;margin:7px 0}
.syllabus-grid,.resource-list,.cinema-grid{grid-template-columns:minmax(0,1fr)}
.phase:nth-child(n){display:block;padding:24px;min-height:0}
.phase h3{font-size:23px}
.phase ul{margin-top:18px}
.cinema-film .film-cover h3{font-size:42px}
.journal-masthead h2{font-size:clamp(45px,12.5vw,64px);line-height:1.25;overflow-wrap:anywhere}
.journal-masthead h2 em{font-size:.9em}
}
